    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                pts.setdefault(grid[r][c], []).append((r, c))

    for color, cells in pts.items():
        s = set(cells)
        others = [p for col, ps in pts.items() if col != color for p in ps]

        def clearance(p):
            if not others:
                return float('inf')
            return min((p[0]-q[0])**2 + (p[1]-q[1])**2 for q in others)

        for r, c in cells:
            for dr, dc in ((1, 1), (1, -1)):
                q = (r + dr, c + dc)
                if q not in s:
