                p = (r, c)
                # Extend outward from the endpoint farther from the other colors.
                if clearance(q) > clearance(p):
                    end, start = q, p
                else:
                    end, start = p, q
                er, ec = end
                vr, vc = end[0] - start[0], end[1] - start[1]
                rr, cc = er + vr, ec + vc
                while 0 <= rr < h and 0 <= cc < w:
