    # continuation is unoccupied.
    for color, cells in positions.items():
        for dr, dc in ((1, 1), (1, -1)):
            for r, c in cells:
                if (r - dr, c - dc) in cells:
                    continue  # not the start of this diagonal run
                run = []
                rr, cc = r, c
                while (rr, cc) in cells:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue
                for er, ec, vr, vc in (
                    (run[0][0], run[0][1], -dr, -dc),
                    (run[-1][0], run[-1][1], dr, dc),
                ):
