                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != bg:
                        continue
                    while 0 <= nr < h and 0 <= nc < w:
                        if out[nr][nc] == bg:
                            out[nr][nc] = color
                        nr += vr
                        nc += vc

    # A singleton can also form the start of a ray when it touches a
    # different-color object diagonally; extend away from that neighbor.
    for color, cells in positions.items():
        if len(cells) != 1:
            continue
        r, c = next(iter(cells))
        for dr, dc in ((1, 1), (1, -1)):
            for sign in (-1, 1):
