                    nr, nc = er + vr, ec + vc
                    if not (0 <= nr < h and 0 <= nc < w) or grid[nr][nc] != bg:
                        continue

                    # Extend only from an exposed endpoint, not a junction
                    # adjoining another part of the pattern.
                    exposed = True
                    for ar in (-1, 0, 1):
                        for ac in (-1, 0, 1):
                            if ar == ac == 0:
                                continue
                            q = (er + ar, ec + ac)
                            if q == partner or q == end:
                                continue
                            qr, qc = q
                            if 0 <= qr < h and 0 <= qc < w and grid[qr][qc] != bg:
                                exposed = False
                    if not exposed:
                        continue

                    while 0 <= nr < h and 0 <= nc < w:
                        if grid[nr][nc] != bg:
                            break
                        out[nr][nc] = color
                        nr += vr
                        nc += vc
    return out
